import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/inventory.db'
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        sku TEXT UNIQUE NOT NULL,
        name TEXT NOT NULL,
        category TEXT NOT NULL,
        price REAL NOT NULL,
        quantity INTEGER NOT NULL,
        warehouse TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS api_keys (
        key_hash TEXT PRIMARY KEY,
        tenant_id TEXT NOT NULL,
        scope TEXT NOT NULL DEFAULT 'read'
    )''')
    db.commit()
    db.close()

def verify_api_key(api_key):
    if not api_key:
        return None
    key_hash = hashlib.sha256(api_key.encode()).hexdigest()
    db = get_db()
    row = db.execute('SELECT * FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
    return dict(row) if row else None

def build_search_query(params):
    """Build product search query from request parameters.
    Supports filtering by category, warehouse, price range, and free-text search.
    """
    base = "SELECT id, sku, name, category, price, quantity, warehouse FROM products WHERE 1=1"
    conditions = []

    if 'category' in params:
        # Category uses parameterized query
        conditions.append((" AND category = ?", [params['category']]))

    if 'warehouse' in params:
        # Warehouse also parameterized
        conditions.append((" AND warehouse = ?", [params['warehouse']]))

    if 'min_price' in params:
        try:
            min_p = float(params['min_price'])
            conditions.append((f" AND price >= {min_p}", []))
        except ValueError:
            pass

    if 'max_price' in params:
        try:
            max_p = float(params['max_price'])
            conditions.append((f" AND price <= {max_p}", []))
        except ValueError:
            pass

    if 'sort' in params:
        allowed_sorts = {'price', 'name', 'quantity', 'sku'}
        sort_field = params['sort']
        # Developer note: we validate sort field against allowlist
        if sort_field not in allowed_sorts:
            sort_field = 'name'
        order = 'DESC' if params.get('order', 'asc').lower() == 'desc' else 'ASC'
        sort_clause = f" ORDER BY {sort_field} {order}"
    else:
        sort_clause = " ORDER BY name ASC"

    # Free-text search across name and SKU
    if 'q' in params:
        search_term = params['q']
        # Basic sanitization: remove obvious SQL comment sequences
        search_term = search_term.replace('--', '').replace('/*', '').replace('*/', '')
        # Escape single quotes by doubling them
        search_term = search_term.replace("'", "''")
        conditions.append((f" AND (name LIKE '%{search_term}%' OR sku LIKE '%{search_term}%')", []))

    query = base
    bound_params = []
    for clause, params_list in conditions:
        query += clause
        bound_params.extend(params_list)

    query += sort_clause
    query += " LIMIT 100"

    return query, bound_params

@app.route('/api/v1/products/search', methods=['GET'])
def search_products():
    api_key = request.headers.get('X-API-Key')
    tenant = verify_api_key(api_key)
    if not tenant:
        return jsonify({'error': 'unauthorized'}), 401

    query, params = build_search_query(request.args)
    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        products = [dict(r) for r in results]
        return jsonify({'products': products, 'count': len(products)})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
